  .split(";")
  .map(group => group.trim())
  .filter(Boolean);

const securityGroupsArray = securityGroupsFromSteps
  .split(";")
  .map(group => group.trim())
  .filter(Boolean);

// Merge arrays and remove duplicates
const allSecurityGroups = [...new Set([...initiatingSecurityGroupsArray, ...securityGroupsArray])];

// Create an array of objects containing ID and Role for each security group
const rolesArray = allSecurityGroups.map((role, index) => {
  return { ID: index + 1, Role: role };
});

// Return the array of roles objects
return rolesArray;

