const variable = "contacts";

return new Promise((resolve, reject) => {
    const startTime = Date.now();
    const timeout = 5000;

    function checkVariable() {
        if (window[variable] !== undefined && window[variable] !== null) {
            // Only map if contacts exist
            const contacts = window[variable];
            const result = Object.entries(contacts).map(([name, numbers]) => ({
                name: name,
                number: numbers
            }));
            resolve(result);
        } else if (Date.now() - startTime < timeout) {
            setTimeout(checkVariable, 100);
        } else {
            // Return null instead of rejecting when timeout occurs
            resolve(null);
        }
    }

    checkVariable();
});

